(r, big) => {
    const W = big ? 2000000000 : r.int(1, 8), rows = big ? 2000 : r.int(1, 5);
    const wall = [];
    for (let i = 0; i < rows; i++) {
      const k = Math.min(W - 1, big ? 9 : r.int(0, 4));
      const cuts = k > 0 ? r.distinct(k, 1, W - 1) : [];
      if (big && i % 2) cuts[0] = 1000000000;
      const uniq = [...new Set(cuts)].sort((a, b) => a - b);
      const row = []; let prev = 0;
      for (const c of uniq) { row.push(c - prev); prev = c; }
      row.push(W - prev);
      wall.push(row);
    }
    return [wall];
  }

