function fewestCutBricks(wall: number[][]): number {
  const candidates = new Set<number>();
  for (const row of wall) {
    let x = 0;
    for (let j = 0; j < row.length - 1; j++) { x += row[j]; candidates.add(x); }
  }
  let best = wall.length;
  for (const x of candidates) {
    let cut = 0;
    for (const row of wall) {
      let sum = 0, onSeam = false;
      for (let j = 0; j < row.length - 1 && sum < x; j++) { sum += row[j]; if (sum === x) onSeam = true; }
      if (!onSeam) cut++;
    }
    best = Math.min(best, cut);
  }
  return best;
}

