    def fewestCutBricks(self, wall: List[List[int]]) -> int:
        candidates = set()
        for row in wall:
            x = 0
            for w in row[:-1]:
                x += w
                candidates.add(x)
        best = len(wall)
        for x in candidates:
            cut = 0
            for row in wall:
                s, on_seam = 0, False
                for w in row[:-1]:
                    s += w
                    if s == x:
                        on_seam = True
                    if s >= x:
                        break
                if not on_seam:
                    cut += 1
            best = min(best, cut)
        return best

