function fewestCutBricks(wall: number[][]): number {
  const seams = new Map<number, number>();
  let best = 0;
  for (const row of wall) {
    let x = 0;
    for (let j = 0; j < row.length - 1; j++) {
      x += row[j];
      const c = (seams.get(x) ?? 0) + 1;
      seams.set(x, c);
      if (c > best) best = c;
    }
  }
  return wall.length - best;
}

